// Import Material Design 3 Web Components
import '@material/web/button/filled-button.js';
import '@material/web/button/filled-tonal-button.js';
import '@material/web/button/outlined-button.js';
import '@material/web/textfield/outlined-text-field.js';
import '@material/web/progress/circular-progress.js';
import '@material/web/slider/slider.js';
import '@material/web/icon/icon.js';
import '@material/web/iconbutton/icon-button.js';

// Import WASM module generated by wasm-pack
import init, { QuantumWormholeEngine } from '../crate/pkg/quantum_wormhole.js';

// DOM Elements
const canvas = document.getElementById('wormhole-canvas') as HTMLCanvasElement;
const ctx = canvas.getContext('2d', { alpha: false })!;
const canvasFrame = document.getElementById('canvas-frame') as HTMLElement;

const inputName = document.getElementById('input-name') as any;
const inputDob = document.getElementById('input-dob') as any;
const btnOpenDatepicker = document.getElementById('btn-open-datepicker') as HTMLElement;

const standbyOverlay = document.getElementById('standby-overlay') as HTMLElement;

const btnToggleEngine = document.getElementById('btn-toggle-engine') as any;
const engineBtnIcon = document.getElementById('engine-btn-icon') as HTMLElement;
const engineBtnText = document.getElementById('engine-btn-text') as HTMLElement;

const btnSave = document.getElementById('btn-save') as HTMLElement;

const sliderWarp = document.getElementById('slider-warp') as any;
const sliderFlux = document.getElementById('slider-flux') as any;
const sliderSpeed = document.getElementById('slider-speed') as any;

const valWarp = document.getElementById('val-warp') as HTMLElement;
const valFlux = document.getElementById('val-flux') as HTMLElement;
const valSpeed = document.getElementById('val-speed') as HTMLElement;

const hudFps = document.getElementById('hud-fps') as HTMLElement;
const hudHash = document.getElementById('hud-hash') as HTMLElement;
const hudStatus = document.getElementById('hud-status') as HTMLElement;
const statusDot = document.getElementById('status-dot') as HTMLElement;
const loader = document.getElementById('canvas-loader') as HTMLElement;

const teleHorizon = document.getElementById('tele-horizon') as HTMLElement;
const teleEnergy = document.getElementById('tele-energy') as HTMLElement;
const teleDoppler = document.getElementById('tele-doppler') as HTMLElement;

// M3 Date Picker Elements
const m3DateDialog = document.getElementById('m3-date-dialog') as HTMLDialogElement;
const m3DatePickerSelected = document.getElementById('m3-date-picker-selected') as HTMLElement;
const m3MonthYearTitle = document.getElementById('m3-month-year-title') as HTMLElement;
const m3DaysContainer = document.getElementById('m3-days-container') as HTMLElement;
const btnPrevMonth = document.getElementById('btn-prev-month') as HTMLElement;
const btnNextMonth = document.getElementById('btn-next-month') as HTMLElement;
const btnDateCancel = document.getElementById('btn-date-cancel') as HTMLElement;
const btnDateConfirm = document.getElementById('btn-date-confirm') as HTMLElement;

// App Engine State
type EngineState = 'STOPPED' | 'RUNNING';

let engine: QuantumWormholeEngine | null = null;
let engineState: EngineState = 'STOPPED';
let animationFrameId: number | null = null;
let lastFrameTime = performance.now();
let frameCount = 0;
let fpsTimer = performance.now();
let timeOffset = 0;
let wasRunningBeforeHide = false;

// M3 DatePicker State
let currentSelectedDate = new Date(2000, 0, 1);
let activePickerYear = 2000;
let activePickerMonth = 0;
let tempSelectedDate = new Date(2000, 0, 1);

// Compute SHA-256 Hash for input seed display
async function computeHash(str: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(str);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// Update telemetry display metrics
async function updateTelemetry(name: string, dob: string) {
  const hashStr = await computeHash(`${name}:${dob}`);
  const shortHash = `0x${hashStr.substring(0, 8).toUpperCase()}`;
  hudHash.textContent = shortHash;

  const h1 = parseInt(hashStr.substring(0, 4), 16);
  const h2 = parseInt(hashStr.substring(4, 8), 16);
  const h3 = parseInt(hashStr.substring(8, 12), 16);

  const horizonKm = (12.4 + (h1 % 850) / 10).toFixed(2);
  const energyPev = ((h2 % 9000) / 100 + 10.5).toFixed(1);
  const dopplerZ = ((h3 % 1000) / 2000 + 0.15).toFixed(3);

  teleHorizon.textContent = `${horizonKm} km`;
  teleEnergy.textContent = `${energyPev} PeV`;
  teleDoppler.textContent = `z = +${dopplerZ}`;
}

// Render a single frame from WASM engine
function renderSingleFrame() {
  if (!engine) return;

  const name = inputName.value || 'Mozi Quantum';
  const dob = inputDob.value || '2000-01-01';
  const warp = parseFloat(sliderWarp.value ?? '1.0');
  const flux = parseFloat(sliderFlux.value ?? '1.0');

  // Compute 512x512 RGBA array from Rust WASM
  const pixelArray = engine.render(name, dob, timeOffset, warp, flux);
  
  const imgData = new ImageData(
    new Uint8ClampedArray(pixelArray.buffer as ArrayBuffer, pixelArray.byteOffset, pixelArray.byteLength),
    512,
    512
  );
  ctx.putImageData(imgData, 0, 0);

  updateTelemetry(name, dob);
}

// Main Animation Loop
function renderLoop(now: number) {
  if (engineState !== 'RUNNING' || !engine) return;

  const delta = (now - lastFrameTime) / 1000;
  lastFrameTime = now;

  // FPS metric calculation
  frameCount++;
  if (now - fpsTimer >= 500) {
    const currentFps = Math.round((frameCount * 1000) / (now - fpsTimer));
    hudFps.textContent = currentFps.toString();
    frameCount = 0;
    fpsTimer = now;
  }

  const speedMultiplier = parseFloat(sliderSpeed.value ?? '1.0');
  timeOffset += delta * speedMultiplier;

  renderSingleFrame();

  animationFrameId = requestAnimationFrame(renderLoop);
}

// Start Engine Execution
function startEngine() {
  if (!engine) return;

  engineState = 'RUNNING';
  standbyOverlay.classList.add('hidden');

  // Update Buttons UI
  engineBtnIcon.textContent = 'stop';
  engineBtnText.textContent = '停止引擎';

  // Update Status HUD
  hudStatus.textContent = '运行中';
  statusDot.className = 'status-dot active';

  lastFrameTime = performance.now();
  fpsTimer = performance.now();
  frameCount = 0;

  if (animationFrameId !== null) cancelAnimationFrame(animationFrameId);
  animationFrameId = requestAnimationFrame(renderLoop);
}

// Stop Engine Execution completely (0% CPU)
function stopEngine() {
  engineState = 'STOPPED';
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  standbyOverlay.classList.remove('hidden');

  // Update Buttons UI
  engineBtnIcon.textContent = 'play_arrow';
  engineBtnText.textContent = '启动量子引擎';

  // Update Status HUD
  hudStatus.textContent = '待机';
  statusDot.className = 'status-dot';
  hudFps.textContent = '0';
}

// Format date to YYYY-MM-DD
function formatDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// Format date for M3 Picker display
function formatM3DateDisplay(d: Date): string {
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
}

// Render Calendar Days Grid for M3 DatePicker
function renderM3Calendar() {
  m3MonthYearTitle.textContent = `${activePickerYear}年 ${activePickerMonth + 1}月`;
  m3DatePickerSelected.textContent = formatM3DateDisplay(tempSelectedDate);

  m3DaysContainer.innerHTML = '';

  const firstDayOfWeek = new Date(activePickerYear, activePickerMonth, 1).getDay();
  const totalDays = new Date(activePickerYear, activePickerMonth + 1, 0).getDate();

  // Empty cells before first day
  for (let i = 0; i < firstDayOfWeek; i++) {
    const emptyCell = document.createElement('div');
    emptyCell.className = 'm3-day-cell empty';
    m3DaysContainer.appendChild(emptyCell);
  }

  // Days cells
  for (let day = 1; day <= totalDays; day++) {
    const cell = document.createElement('div');
    cell.className = 'm3-day-cell';
    cell.textContent = day.toString();

    const cellDate = new Date(activePickerYear, activePickerMonth, day);
    if (
      cellDate.getFullYear() === tempSelectedDate.getFullYear() &&
      cellDate.getMonth() === tempSelectedDate.getMonth() &&
      cellDate.getDate() === tempSelectedDate.getDate()
    ) {
      cell.classList.add('selected');
    }

    cell.addEventListener('click', () => {
      tempSelectedDate = new Date(activePickerYear, activePickerMonth, day);
      renderM3Calendar();
    });

    m3DaysContainer.appendChild(cell);
  }
}

// Open M3 Date Picker Dialog
function openDatePicker() {
  const parts = (inputDob.value || '2000-01-01').split('-').map(Number);
  if (parts.length === 3) {
    currentSelectedDate = new Date(parts[0], parts[1] - 1, parts[2]);
  } else {
    currentSelectedDate = new Date(2000, 0, 1);
  }

  tempSelectedDate = new Date(currentSelectedDate);
  activePickerYear = tempSelectedDate.getFullYear();
  activePickerMonth = tempSelectedDate.getMonth();

  renderM3Calendar();
  m3DateDialog.showModal();
}

// Initialize WASM and Application Event Listeners
async function initApp() {
  try {
    loader.classList.remove('hidden');
    // Load WASM package
    await init();
    engine = new QuantumWormholeEngine(512, 512);

    loader.classList.add('hidden');

    // Initial calculation of telemetry
    const initialName = inputName.value || 'Mozi Quantum';
    const initialDob = inputDob.value || '2000-01-01';
    updateTelemetry(initialName, initialDob);

    // Initial preview render frame on canvas background
    renderSingleFrame();

    // Event Listener: Click on Canvas Frame or Overlay to toggle engine
    canvasFrame.addEventListener('click', () => {
      if (engineState === 'STOPPED') {
        startEngine();
      }
    });

    // Event Listener: Main Engine Toggle (Start / Stop)
    btnToggleEngine.addEventListener('click', () => {
      if (engineState === 'STOPPED') {
        startEngine();
      } else {
        stopEngine();
      }
    });

    // Event Listener: Export High Res Image
    btnSave.addEventListener('click', () => {
      const link = document.createElement('a');
      const name = (inputName.value || 'quantum').replace(/\s+/g, '_');
      link.download = `wormhole_${name}_512x512.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    });

    // M3 Date Picker Event Listeners
    inputDob.addEventListener('click', openDatePicker);
    btnOpenDatepicker.addEventListener('click', (e: Event) => {
      e.stopPropagation();
      openDatePicker();
    });

    btnPrevMonth.addEventListener('click', () => {
      activePickerMonth--;
      if (activePickerMonth < 0) {
        activePickerMonth = 11;
        activePickerYear--;
      }
      renderM3Calendar();
    });

    btnNextMonth.addEventListener('click', () => {
      activePickerMonth++;
      if (activePickerMonth > 11) {
        activePickerMonth = 0;
        activePickerYear++;
      }
      renderM3Calendar();
    });

    btnDateCancel.addEventListener('click', () => {
      m3DateDialog.close();
    });

    btnDateConfirm.addEventListener('click', () => {
      currentSelectedDate = new Date(tempSelectedDate);
      inputDob.value = formatDate(currentSelectedDate);
      m3DateDialog.close();
      onInputParamChange();
    });

    // Input listeners (Trigger on-demand single render if stopped)
    function onInputParamChange() {
      updateTelemetry(inputName.value || 'Mozi Quantum', inputDob.value || '2000-01-01');
      if (engineState !== 'RUNNING') {
        renderSingleFrame();
      }
    }

    inputName.addEventListener('input', onInputParamChange);

    // Sliders listeners
    sliderWarp.addEventListener('input', () => {
      valWarp.textContent = parseFloat(sliderWarp.value).toFixed(1);
      if (engineState !== 'RUNNING') renderSingleFrame();
    });

    sliderFlux.addEventListener('input', () => {
      valFlux.textContent = parseFloat(sliderFlux.value).toFixed(1);
      if (engineState !== 'RUNNING') renderSingleFrame();
    });

    sliderSpeed.addEventListener('input', () => {
      valSpeed.textContent = parseFloat(sliderSpeed.value).toFixed(1);
    });

    // Visibility Change Handler to auto-pause WASM when tab is hidden
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') {
        if (engineState === 'RUNNING') {
          wasRunningBeforeHide = true;
          stopEngine();
        }
      } else if (document.visibilityState === 'visible') {
        if (wasRunningBeforeHide) {
          wasRunningBeforeHide = false;
          startEngine();
        }
      }
    });

  } catch (err) {
    console.error('Failed to initialize Rust WASM Quantum Engine:', err);
    loader.querySelector('.loader-text')!.textContent = 'WASM 引擎初始化失败';
  }
}

// Run Application Init
initApp();
